//! ⚡️ Lowpoly artifact — OpText/OpBinary codecs for `LowpolyMutation`. Mutation apply/inverse (via
//! `protocol::Mutation`/`protocol::SemanticMutation`, generated by `#[derive(dsl_derive::Mutations)]`
//! on the dispatch enum in `../🦀️component.rs`) is NOT this file's concern; this file only wires the
//! operation-log line/binary encodings. `serde_json`'s compact (single-line, declaration-order)
//! encoding satisfies `OpText`/`OpBinary`'s laws directly: `print_op` never contains `\n`,
//! `parse_op(op.print_op()) == op`, and encoding is deterministic — the same approach the sibling
//! `shooting`/`playground` facets already migrated to under this ticket.

pub use crate::artifacts::lowpoly::schema::mutations::{LowpolyMutation, PixelRun};

//#region 📖️SemioGrammar
/// 📖️ Normative handcrafted text grammar for this facet (`dialect grammar`).
pub const COMPONENT_GRAMMAR_SEMIO: &str = include_str!("📖️component.grammar.semio");
pub const COMPONENT_GRAMMAR_PATH: &str = concat!(module_path!(), "::📖️component.grammar.semio");
//#endregion 📖️SemioGrammar

//#region 🔖️OpText
impl protocol::OpText for LowpolyMutation {
    fn parse_op(line: &str) -> Result<Self, store::TextError> {
        serde_json::from_str(line).map_err(|e| store::__rt::field_error(format!("invalid lowpoly mutation line: {e}")))
    }
    fn print_op(&self) -> String {
        serde_json::to_string(self).expect("LowpolyMutation always serializes")
    }
}
//#endregion 🔖️OpText

//#region 🔖️OpBinary
impl protocol::OpBinary for LowpolyMutation {
    fn encode_op(&self) -> Result<Vec<u8>, protocol::ProtocolError> {
        Ok(serde_json::to_vec(self).expect("LowpolyMutation always serializes"))
    }
    fn decode_op(bytes: &[u8]) -> Result<Self, protocol::ProtocolError> {
        serde_json::from_slice(bytes).map_err(|e| protocol::ProtocolError::Malformed { what: "lowpoly-mutation", offset: 0, detail: e.to_string() })
    }
}
//#endregion 🔖️OpBinary

//#region 🧪️Tests
#[cfg(test)]
mod tests {
    use super::*;
    use crate::artifacts::lowpoly::schema::default_snapshot;
    use crate::artifacts::lowpoly::mutations::{create_object, delete_object, edit_paint_layer, insert_paint_layer, rename_object};
    use protocol::{OpBinary, OpText};

    fn tiny_mesh_json() -> String {
        semio_framework_3d::mesh::HalfedgeMesh::box_prim(1.0, 1.0, 1.0).expect("box prim").to_json().expect("mesh json")
    }

    fn tiny_object(id: &str, name: &str) -> crate::artifacts::lowpoly::LowpolyObject {
        crate::artifacts::lowpoly::LowpolyObject {
            id: id.into(),
            name: name.into(),
            transform: Default::default(),
            smooth_shading: false,
            mesh_json: tiny_mesh_json(),
            paint_layers: vec![crate::artifacts::lowpoly::LowpolyPaintLayer::new("Base")],
        }
    }

    /// 🧪️ One representative value per variant — reused by the round-trip law test below.
    fn demo_mutation_cases() -> Vec<LowpolyMutation> {
        let projection = default_snapshot();
        let object_id = projection.objects[0].id.clone();
        vec![
            LowpolyMutation::CreateObject(create_object::mutation::CreateObject { index: 1, object: tiny_object("obj-100", "Box") }),
            LowpolyMutation::DeleteObject(delete_object::mutation::DeleteObject { id: object_id.clone() }),
            LowpolyMutation::ReorderObjects(crate::artifacts::lowpoly::mutations::reorder_objects::mutation::ReorderObjects { id: object_id.clone(), to_index: 0 }),
            LowpolyMutation::RenameObject(rename_object::mutation::RenameObject { id: object_id.clone(), new_name: "Renamed".into() }),
            LowpolyMutation::ChangeObjectSmoothShading(crate::artifacts::lowpoly::mutations::change_object_smooth_shading::mutation::ChangeObjectSmoothShading { id: object_id.clone(), new_smooth_shading: true }),
            LowpolyMutation::MoveObject(crate::artifacts::lowpoly::mutations::move_object::mutation::MoveObject { id: object_id.clone(), new_position: [1.0, 2.0, 3.0] }),
            LowpolyMutation::RotateObject(crate::artifacts::lowpoly::mutations::rotate_object::mutation::RotateObject { id: object_id.clone(), new_rotation: [0.1, 0.2, 0.3] }),
            LowpolyMutation::ScaleObject(crate::artifacts::lowpoly::mutations::scale_object::mutation::ScaleObject { id: object_id.clone(), new_scale: [2.0, 2.0, 2.0] }),
            LowpolyMutation::ReplaceObjectMesh(crate::artifacts::lowpoly::mutations::replace_object_mesh::mutation::ReplaceObjectMesh { id: object_id.clone(), new_mesh_json: tiny_mesh_json() }),
            LowpolyMutation::InsertPaintLayer(insert_paint_layer::mutation::InsertPaintLayer { object_id: object_id.clone(), index: 1, layer: crate::artifacts::lowpoly::LowpolyPaintLayer::new("Detail") }),
            LowpolyMutation::RemovePaintLayer(crate::artifacts::lowpoly::mutations::remove_paint_layer::mutation::RemovePaintLayer { object_id: object_id.clone(), index: 0 }),
            LowpolyMutation::RenamePaintLayer(crate::artifacts::lowpoly::mutations::rename_paint_layer::mutation::RenamePaintLayer { object_id: object_id.clone(), index: 0, new_name: "Top".into() }),
            LowpolyMutation::ChangePaintLayerVisible(crate::artifacts::lowpoly::mutations::change_paint_layer_visible::mutation::ChangePaintLayerVisible { object_id: object_id.clone(), index: 0, new_visible: false }),
            LowpolyMutation::ChangePaintLayerOpacity(crate::artifacts::lowpoly::mutations::change_paint_layer_opacity::mutation::ChangePaintLayerOpacity { object_id: object_id.clone(), index: 0, new_opacity: 0.5 }),
            LowpolyMutation::ChangePaintLayerBlendMode(crate::artifacts::lowpoly::mutations::change_paint_layer_blend_mode::mutation::ChangePaintLayerBlendMode { object_id: object_id.clone(), index: 0, new_blend_mode: "multiply".into() }),
            LowpolyMutation::EditPaintLayer(edit_paint_layer::mutation::EditPaintLayer { object_id, layer_index: 0, runs: vec![PixelRun { offset: 12, bytes: vec![255, 0, 0, 255] }, PixelRun { offset: 400, bytes: vec![0, 255, 0, 255, 0, 0, 0, 128] }] }),
        ]
    }

    #[test]
    fn op_text_binary_roundtrip_law() {
        for mutation in demo_mutation_cases() {
            let printed = mutation.print_op();
            assert!(!printed.contains('\n'), "print_op must be one line, got {printed:?}");
            let parsed = <LowpolyMutation as OpText>::parse_op(&printed).unwrap_or_else(|e| panic!("parse_op({printed:?}) failed: {e}"));
            assert_eq!(parsed, mutation, "print_op/parse_op round-trip mismatch (printed {printed:?})");

            let encoded = mutation.encode_op().unwrap_or_else(|e| panic!("encode_op failed: {e}"));
            let decoded = <LowpolyMutation as OpBinary>::decode_op(&encoded).unwrap_or_else(|e| panic!("decode_op failed: {e}"));
            assert_eq!(decoded, mutation, "encode_op/decode_op round-trip mismatch");
        }
    }

    #[test]
    fn op_text_parse_rejects_garbage() {
        let result = <LowpolyMutation as protocol::OpText>::parse_op("not json at all");
        assert!(result.is_err());
    }
}
//#endregion 🧪️Tests
